-- Kigali Hardware Ltd: 1 x 40ft container, Dar es Salaam port -> Rusumo -> ITEC Kigali warehouse.
-- Every record, status, warehouse movement, journal entry, notification and (unsent) email of the job,
-- exactly as the system produced it when the staff played it through.
--
-- Import ONCE into superocbs_superocbs_lms after migrations 030-033. Needs the sample data
-- (ITEC Kigali Main Warehouse, RAD 482 K, Samuel Niyonzima, Rusumo, Great Lakes Clearing & Forwarding).
-- Links are found by email / plate / licence / name, never by id, so it fits any database.
-- It runs as one transaction: if any line fails, nothing is saved.
-- The demo emails are kept in the outbox for show but marked so they are never sent.

SET NAMES utf8mb4;
START TRANSACTION;

-- Journal numbers continue from whatever the books already hold.
SET @jn := (SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(entry_no, '-', -1) AS UNSIGNED)), 0) FROM gl_journal_entries WHERE entry_no LIKE 'JRN-2026-%');

