INSERT INTO customers (customer_code, customer_name, customer_type, contact_name, phone, email, address, district, tin_number, payment_terms_days, credit_limit, currency, status, notes, deleted_at, created_at) VALUES ('CUS-2026-0003', 'Kigali Hardware Ltd', 'corporate', 'Jean Claude Mugabo', '+250 788 455 120', 'imports@kigalihardware.rw', 'KN 5 Rd, Nyarugenge', 'Nyarugenge', '109887766', '30', '50000.00', 'USD', 'active', 'Importer of building materials from China, through Dar es Salaam.', NULL, '2026-10-01 16:52:10');
SET @customers_17 = LAST_INSERT_ID();

