INSERT INTO email_outbox (message_key, category, to_email, to_name, user_id, subject, body_html, body_text, entity_type, entity_id, status, provider_id, error, attempts, sent_at, created_at) VALUES ('kh-demo-quote-9', 'notification', 'imports@kigalihardware.rw', 'Jean Claude Mugabo', NULL, 'Quotation for transport, Dar es Salaam to ITEC Kigali Main Warehouse', '<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Quotation for transport, Dar es Salaam to ITEC Kigali Main Warehouse</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Transport quotation — Dar es Salaam to ITEC Kigali Main Warehouse</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Dear Jean Claude Mugabo,</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Thank you for your enquiry. We are pleased to offer the following terms for carrying your goods from Dar es Salaam to ITEC Kigali Main Warehouse.</p><p style=\"margin:22px 0 8px;font-size:12px;letter-spacing:.8px;text-transform:uppercase;color:#77828d;font-weight:700\">Our offer</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;margin:0 0 18px;border-collapse:collapse\"><tr><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Detail</th><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Value</th></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Goods to be carried</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Building materials: floor tiles, taps, PVC pipes — 1 x 40ft container (MSKU 7788123)</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Weight</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">22,000 kg</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Collection from</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Dar es Salaam</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Delivery to</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">ITEC Kigali Main Warehouse</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Required by</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">7 October 2026</td></tr><tr><td colspan=\"1\" align=\"right\" style=\"padding:9px 10px;font-size:13px;color:#77828d\">Total price</td><td align=\"right\" style=\"padding:9px 10px;font-size:15px;color:#18222c;font-weight:700;border-top:1px solid #e9edf1\">USD 3,200.00</td></tr></table><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">The price above is for the weight shown and includes carriage from Dar es Salaam to ITEC Kigali Main Warehouse. A heavier load is quoted again, since it takes more of the vehicle.</p><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">This quotation is open for acceptance until 31 October 2026.</p><p style=\"margin:0 0 12px;font-size:14px;line-height:1.6;color:#5b6670\">To accept, simply reply to this message. Please quote reference REQ-2026-0003 in any correspondence.</p></td></tr><tr><td style=\"padding:16px 26px;background:#f7f9fb;border-top:1px solid #e9edf1\"><p style=\"margin:0;font-size:11px;line-height:1.6;color:#8a949e\">Sent by ITEC Cargo ltd. You may reply to this message and it will reach us.</p><p style=\"margin:6px 0 0;font-size:11px;color:#9aa4ad\">Powered by ITEC LTD &copy; 2026</p></td></tr></table></td></tr></table></body></html>', 'Transport quotation — Dar es Salaam to ITEC Kigali Main Warehouse\n\nDear Jean Claude Mugabo,\n\nThank you for your enquiry. We are pleased to offer the following terms for carrying your goods from Dar es Salaam to ITEC Kigali Main Warehouse.\n\nOUR OFFER\n  Detail: Goods to be carried  |  Value: Building materials: floor tiles, taps, PVC pipes — 1 x 40ft container (MSKU 7788123)\n  Detail: Weight  |  Value: 22,000 kg\n  Detail: Collection from  |  Value: Dar es Salaam\n  Detail: Delivery to  |  Value: ITEC Kigali Main Warehouse\n  Detail: Required by  |  Value: 7 October 2026\n  Total price: USD 3,200.00\n\n\nThe price above is for the weight shown and includes carriage from Dar es Salaam to ITEC Kigali Main Warehouse. A heavier load is quoted again, since it takes more of the vehicle.\n\nThis quotation is open for acceptance until 31 October 2026.\n\nTo accept, simply reply to this message. Please quote reference REQ-2026-0003 in any correspondence.\n\nSent by ITEC Cargo ltd. You may reply to this message and it will reach us.\nPowered by ITEC LTD (c) 2026', 'requests', 'REQ-2026-0003', 'skipped', NULL, 'Demo scenario (Kigali Hardware): recorded for show, never sent.', 3, NULL, '2026-10-01 16:52:10');
