INSERT INTO email_outbox (message_key, category, to_email, to_name, user_id, subject, body_html, body_text, entity_type, entity_id, status, provider_id, error, attempts, sent_at, created_at) VALUES ('kh-demo-arrived-10', 'notification', 'imports@kigalihardware.rw', 'Jean Claude Mugabo', NULL, 'Ready for collection at ITEC Kigali Main Warehouse — DEL-2026-0003', '<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Ready for collection at ITEC Kigali Main Warehouse — DEL-2026-0003</title></head><body style=\"margin:0;padding:0;background:#f1f4f7;font-family:Segoe UI,Helvetica,Arial,sans-serif\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#f1f4f7;padding:24px 12px\"><tr><td align=\"center\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;max-width:580px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 2px 10px rgba(20,30,40,.07)\"><tr><td style=\"background:#AD7D00;padding:18px 26px\"><span style=\"color:#ffffff;font-size:16px;font-weight:700;letter-spacing:.4px\">ITEC Cargo ltd</span><span style=\"display:block;color:rgba(255,255,255,.82);font-size:11px;letter-spacing:1.2px;text-transform:uppercase;margin-top:2px\">Logistics Management System</span></td></tr><tr><td style=\"padding:26px\"><h1 style=\"margin:0 0 16px;font-size:19px;line-height:1.35;color:#18222c;font-weight:700\">Ready for collection</h1><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Dear Jean Claude Mugabo,</p><p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#33404c\">Your goods have arrived at ITEC Kigali Main Warehouse and are ready for you to collect. Please bring identification, and quote the reference below.</p><p style=\"margin:22px 0 8px;font-size:12px;letter-spacing:.8px;text-transform:uppercase;color:#77828d;font-weight:700\">Waiting for you</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;margin:0 0 18px;border-collapse:collapse\"><tr><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Detail</th><th align=\"left\" style=\"padding:8px 10px;background:#f2f5f8;border-bottom:2px solid #AD7D00;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:#4a5560;font-weight:700\">Value</th></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Reference</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">DEL-2026-0003</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Goods</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Floor tiles, taps, PVC pipes (building materials)</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Collect from</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">ITEC Kigali Main Warehouse</td></tr><tr><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">Arrived</td><td align=\"left\" style=\"padding:9px 10px;border-bottom:1px solid #e9edf1;font-size:14px;color:#22303c\">2026-10-01 16:52</td></tr></table><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;margin:18px 0;border-collapse:collapse\"><tr><td style=\"padding:7px 12px 7px 0;font-size:13px;color:#77828d;border-bottom:1px solid #e9edf1;white-space:nowrap\">Depot address</td><td style=\"padding:7px 0;font-size:14px;color:#22303c;border-bottom:1px solid #e9edf1;font-weight:600\">Masaka, Kicukiro, Kigali</td></tr><tr><td style=\"p